"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { useEffect, useState } from "react";

type AppShellNavProps = {
  mobile?: boolean;
  compact?: boolean;
  pendingHref?: string | null;
  onNavigate?: (href: string) => void;
  /** Refetch open-incident count when the active project changes. */
  currentProjectId?: string | null;
};

const navItems = [
  {
    href: "/live",
    label: "Live",
    description: "Incidents and uptime",
    icon: "pulse",
  },
  {
    href: "/metrics",
    label: "Metrics",
    description: "Reporting and trends",
    icon: "chart",
  },
  {
    href: "/incidents",
    label: "Incidents",
    description: "Incident explorer",
    icon: "list",
  },
  {
    href: "/control-center",
    label: "Control Center",
    description: "Autonomy and guardrails",
    icon: "shield",
  },
  {
    href: "/onboarding",
    label: "Onboarding",
    description: "Project setup",
    icon: "spark",
  },
  {
    href: "/operations",
    label: "Operations",
    description: "Response workflow",
    icon: "flow",
  },
  {
    href: "/automations",
    label: "Automations",
    description: "Execution catalog",
    icon: "play",
  },
  {
    href: "/chat",
    label: "Agent",
    description: "Inbox and chat focus",
    icon: "spark",
  },
] as const;

export function AppShellNav({
  mobile = false,
  compact = false,
  pendingHref = null,
  onNavigate,
  currentProjectId = null,
}: AppShellNavProps) {
  const pathname = usePathname();
  const openIncidentCount = useOpenIncidentCount(currentProjectId);

  if (mobile) {
    return (
      <nav className="flex gap-2 overflow-x-auto lg:hidden">
        {navItems.map((item) => {
          const isActive =
            pendingHref === item.href ||
            pathname === item.href ||
            pathname.startsWith(`${item.href}/`);

          return (
            <Link
              key={item.href}
              href={item.href}
              onClick={() => onNavigate?.(item.href)}
              className={`vault-nav-link flex min-w-fit items-center gap-2 rounded-xl border border-[rgba(17,24,39,0.08)] bg-[linear-gradient(180deg,#f5f8ff,#e8f0fb)] px-4 py-2 text-sm font-medium shadow-[0_8px_20px_rgba(15,23,42,0.04)] transition ${
                isActive ? "vault-nav-link-active" : ""
              }`}
            >
              <span>{item.label}</span>
              {item.href === "/incidents" ? (
                <OpenIncidentsBadge count={openIncidentCount} />
              ) : null}
            </Link>
          );
        })}
      </nav>
    );
  }

  return (
    <div className="hidden h-full flex-col justify-between lg:flex">
      <div>
        <nav className="space-y-1.5">
          {navItems.map((item) => {
            const isActive =
              pendingHref === item.href ||
              pathname === item.href ||
              pathname.startsWith(`${item.href}/`);

            return (
              <Link
                key={item.href}
                href={item.href}
                onClick={() => onNavigate?.(item.href)}
                className={`vault-sidebar-link vault-nav-link block -mx-2 px-4 py-3 transition ${
                  isActive ? "vault-nav-link-active vault-sidebar-link-active" : ""
                }`}
              >
                <div className={`flex items-center justify-between gap-3 ${compact ? "justify-center" : ""}`}>
                  <div className={compact ? "hidden" : "block min-w-0 flex-1"}>
                    <div className="flex flex-wrap items-center gap-2">
                      <p className="text-sm font-semibold">{item.label}</p>
                      {item.href === "/incidents" ? (
                        <OpenIncidentsBadge count={openIncidentCount} />
                      ) : null}
                    </div>
                    <p className="mt-1 text-xs opacity-70">{item.description}</p>
                  </div>
                  {compact ? (
                    <span className="opacity-80">
                      <NavIcon icon={item.icon} />
                    </span>
                  ) : (
                    <span className="opacity-60">
                      <NavIcon icon={item.icon} />
                    </span>
                  )}
                </div>
              </Link>
            );
          })}
        </nav>
      </div>
    </div>
  );
}

function useOpenIncidentCount(currentProjectId: string | null) {
  const [count, setCount] = useState<number | null>(null);

  useEffect(() => {
    let cancelled = false;

    async function load() {
      try {
        const response = await fetch("/api/incidents/reporting/overview", { cache: "no-store" });
        const data = (await response.json()) as { open_incidents?: number };
        if (!cancelled && typeof data.open_incidents === "number") {
          setCount(data.open_incidents);
        }
      } catch {
        if (!cancelled) {
          setCount(null);
        }
      }
    }

    void load();
    const interval = window.setInterval(load, 45_000);
    return () => {
      cancelled = true;
      window.clearInterval(interval);
    };
  }, [currentProjectId]);

  return count;
}

function OpenIncidentsBadge({ count }: { count: number | null }) {
  if (count === null || count < 1) {
    return null;
  }

  const label = count > 99 ? "99+" : String(count);

  return (
    <span
      title={`${count} open incident${count === 1 ? "" : "s"} in this project`}
      className="inline-flex min-h-[1.125rem] min-w-[1.125rem] shrink-0 items-center justify-center rounded-full border border-[rgba(255,106,61,0.45)] bg-[rgba(255,106,61,0.22)] px-1.5 text-[10px] font-bold tabular-nums leading-none text-[#ffd0bc]"
    >
      {label}
    </span>
  );
}

